// GENERATED by SiteDash — do not edit by hand. Re-run `sitedash init` (mount) to refresh.
import { cookies, headers } from "next/headers";
import { NextResponse } from "next/server";
import { coerceQuery, dispatch, type ApiMethod } from "@sitedash/core";
import {
  captureLead, clearCookie, CSRF_HEADER, isFirstRun, loadServerContext, resolveCtx,
  SESSION_COOKIE, setCookie,
} from "@/sitedash/server";

// Identity is read ONLY from the httpOnly session cookie; permissions are enforced
// server-side by each core handler's can() call. This route owns NOTHING but parsing:
// the route table lives in core's registry, so a handler core ships is a route the host
// exposes the same moment it is installed - no hand-written switch to fall behind.
const SECURE = process.env.NODE_ENV === "production";
const SESSION_MAX_AGE = 60 * 60 * 24 * 7;

const json = (status: number, body: unknown, cookie?: string) =>
  NextResponse.json(body, { status, headers: cookie ? { "set-cookie": cookie } : undefined });

/** A string field of a JSON body, or "" - the body is untrusted, so nothing here assumes a shape. */
function field(body: unknown, key: string): string {
  const v = body && typeof body === "object" ? (body as Record<string, unknown>)[key] : undefined;
  return typeof v === "string" ? v : "";
}

/**
 * The three routes the registry cannot own, because they mint or break the session
 * cookie: login, setup and logout. Every one of them answers with the same body shape
 * the dashboard's client expects ({error} on a refusal), so a failure is a fact the
 * operator can read instead of a spinner.
 */
async function sessionRoute(route: string, body: unknown, ip: string | null, rawToken: string | undefined): Promise<NextResponse> {
  const { deps } = loadServerContext();
  if (route === "login") {
    const email = field(body, "email");
    const password = field(body, "password");
    if (!email || !password) return json(400, { error: "invalid_input" });
    const r = await deps.auth.login(email, password, { ip: ip ?? undefined });
    if (!r.ok || !r.rawToken || !r.csrfToken) return json(r.reason === "rate_limited" ? 429 : 401, { error: r.reason ?? "invalid" });
    return json(200, { csrfToken: r.csrfToken }, setCookie({ name: SESSION_COOKIE, value: r.rawToken, maxAgeSec: SESSION_MAX_AGE, secure: SECURE }));
  }
  if (route === "setup") {
    const email = field(body, "email");
    const password = field(body, "password");
    if (!email || !password) return json(400, { error: "invalid_input" });
    // One Owner, ever: without this gate a second setup call would mint a second
    // all-powerful account on a site that already has one.
    if (!(await isFirstRun(deps))) return json(403, { error: "owner_exists" });
    try {
      const o = await deps.auth.setupOwner({ email, password, name: field(body, "name") || undefined });
      return json(200, { csrfToken: o.csrfToken }, setCookie({ name: SESSION_COOKIE, value: o.rawToken, maxAgeSec: SESSION_MAX_AGE, secure: SECURE }));
    } catch {
      return json(400, { error: "setup_failed" });
    }
  }
  // logout closes THIS session and only this one; the user and their role survive.
  const found = rawToken ? await deps.auth.verifySession(rawToken) : null;
  if (found) await deps.auth.logout(found.session.id);
  return json(200, { ok: true }, clearCookie(SESSION_COOKIE, SECURE));
}

async function handle(req: Request, method: ApiMethod, segments: string[]): Promise<NextResponse> {
  const route = segments.join("/");
  const jar = await cookies();
  const hdrs = await headers();
  const rawToken = jar.get(SESSION_COOKIE)?.value;
  const ip = hdrs.get("x-forwarded-for");

  if (method === "POST" && (route === "login" || route === "setup" || route === "logout")) {
    return sessionRoute(route, await req.json().catch(() => ({})), ip, rawToken);
  }

  // Public capture: no session, no CSRF (a visitor's form has neither). Safety is the
  // honeypot + the per-IP rate limit inside LeadService, and the answer is identical
  // whether or not the honeypot fired, so a bot cannot probe it.
  if (method === "POST" && route === "lead") {
    const body = await req.json().catch(() => ({}));
    const res = await captureLead((body ?? {}) as Record<string, unknown>, ip ?? undefined);
    if (res.reason === "rate_limited") return json(429, { ok: false });
    return json(200, { ok: true });
  }

  const { deps } = loadServerContext();
  const ctx = await resolveCtx(deps, rawToken, hdrs.get(CSRF_HEADER) ?? undefined, ip);
  if (method === "GET" && route === "me") return json(200, { userId: ctx.userId, csrfOk: ctx.csrfOk });
  const raw = method === "GET" ? coerceQuery(route, new URL(req.url).searchParams) : await req.json().catch(() => ({}));
  const res = await dispatch(deps, ctx, { method, route, raw });
  return json(res.status, res.body);
}

/**
 * `[...path]` gives the catch-all segments. A registry name ("articles.list") arrives as
 * ONE segment - dots are legal in a path segment - and a name with no segment at all
 * (an empty prefix hit) is reported as unknown rather than guessed to be something.
 */
function seg(params: Promise<{ path?: string[] }>): Promise<string[]> {
  return params.then((v) => v.path ?? []);
}

export async function GET(req: Request, route: { params: Promise<{ path?: string[] }> }) {
  return handle(req, "GET", await seg(route.params));
}
export async function POST(req: Request, route: { params: Promise<{ path?: string[] }> }) {
  return handle(req, "POST", await seg(route.params));
}
